def count_blocks(grid):
    h = len(grid)
    w = len(grid[0])
    blocks = {}
    for c in range(1, min(h, 5)):
        for r in range(1, min(w, 5)):
            if grid[c-1][r-1] == grid[c][r-1] == grid[c-1][r] == grid[c][r]:
